package store.report;
import store.model.*;import store.service.StoreService;import java.util.*;
public final class ReportService{private final StoreService s;public ReportService(StoreService s){this.s=s;}public void printAll(){System.out.println("STOCK REPORT");for(Product p:s.catalog.products())System.out.printf("%s=%d%n",p.id(),p.stock());System.out.println("SALES BY PRODUCT REPORT");for(var e:s.sold().entrySet())System.out.printf("%s=%d%n",e.getKey(),e.getValue());System.out.println("ORDERS BY STATUS REPORT");for(var e:s.statusCounts().entrySet())System.out.printf("%s=%d%n",e.getKey(),e.getValue());System.out.printf(Locale.US,"CASHFLOW SUMMARY REPORT%nINFLOW=%.2f OUTFLOW=%.2f NET=%.2f%n",s.inflow(),s.outflow(),s.net());System.out.println("RETURNS/REFUNDS REPORT");for(ReturnRequest r:s.db.returns.values())System.out.printf(Locale.US,"%s refund=%.2f%n",r.id(),r.refundTotal());System.out.println("RESTOCKING REPORT");for(Restock r:s.db.restocks.values())System.out.printf(Locale.US,"%s product=%s supplier=%s quantity=%d total=%.2f%n",r.id(),r.product().id(),r.supplier().id(),r.quantity(),r.total());}}
